package com.sarathi.geckotest;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.security.KeyStore;import org.json.JSONObject;
/** Each native engine selects its own vault; callers cannot choose another profile. */
final class SecureSettings {
 private static String entry(int profile){if(profile<1||profile>MonitorService.PROFILE_COUNT)throw new IllegalArgumentException("Invalid applicant");return "config-profile-"+profile;}
 private static javax.crypto.SecretKey key()throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("mparivahan-config")){KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder("mparivahan-config",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());gen.generateKey();}return (javax.crypto.SecretKey)store.getKey("mparivahan-config",null);}
 private static JSONObject decrypt(Context c,String entry)throws Exception{String saved=c.getSharedPreferences("secure",0).getString(entry,"");if(saved.isEmpty())return new JSONObject();String[] fields=saved.split(":",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(fields[0],Base64.NO_WRAP)));return new JSONObject(new String(cipher.doFinal(Base64.decode(fields[1],Base64.NO_WRAP)),java.nio.charset.StandardCharsets.UTF_8));}
 static synchronized JSONObject read(Context c,int profile)throws Exception{return decrypt(c,entry(profile));}
 static synchronized void write(Context c,int profile,JSONObject values)throws Exception{JSONObject merged=read(c,profile);for(String k:new String[]{"botToken","chatId","chatId2"})if(values.has(k))merged.put(k,values.getString(k));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String data=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(merged.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),Base64.NO_WRAP);if(!c.getSharedPreferences("secure",0).edit().putString(entry(profile),data).commit())throw new IllegalStateException("Could not save Telegram settings");}
 static synchronized void remove(Context c,int profile){if(!c.getSharedPreferences("secure",0).edit().remove(entry(profile)).commit())throw new IllegalStateException("Could not remove Telegram settings");}
 static synchronized void importLegacy(Context c,int profile)throws Exception{JSONObject legacy=decrypt(c,"config");if(legacy.optString("botToken").isEmpty())throw new IllegalStateException("No legacy settings exist inside this installation. A fresh install or different package cannot read the old Android Keystore vault. Use an encrypted settings export from the old app.");write(c,profile,legacy);}
}
